import assert from "node:assert/strict";
import { createHash, randomBytes } from "node:crypto";
import { mkdtemp, readdir, readFile, rm, writeFile } from "node:fs/promises";
import http from "node:http";
import net from "node:net";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { after, before, describe, it } from "node:test";

import { InvalidKeyError, parseKey } from "../src/blobs.js";
import { startServer, type RunningServer } from "../src/server.js";

interface Reply {
  status: number;
  headers: http.IncomingHttpHeaders;
  body: string;
  bytes: Buffer;
}

const sha256 = (data: string | Buffer): string => createHash("sha256").update(data).digest("hex");

/**
 * Deterministic pseudo-random raw keys built from a mix of plain characters,
 * separators, dots, percent-escapes of arbitrary bytes and broken escapes.
 */
function arbitraryKeys(seed: number, count: number): string[] {
  const rand = (n: number): number => {
    seed = (seed * 1103515245 + 12345) & 0x7fffffff;
    return seed % n;
  };
  const pieces = ["a", "0", "Z", "-", "_", "~", ".", "..", "/", "%2F", "%2e", "%00", "%", "%g1", "%C3%A9", "%F0%9F%98%80"];
  const keys: string[] = [];
  for (let i = 0; i < count; i++) {
    let key = "";
    const len = rand(8);
    for (let j = 0; j < len; j++) {
      key += rand(3) === 0 ? `%${rand(256).toString(16).padStart(2, "0")}` : pieces[rand(pieces.length)];
    }
    keys.push(key);
  }
  return keys;
}

